const archivePage=(path,title,items,isDeep)=>{
 const r=rootOf(path);
 const links='<nav class="archive-shelf-tabs" aria-label="Browse publication eras">'+
  '<a href="'+r+'latest/">Latest <span>'+current.length+'</span></a>'+
  '<a href="'+r+'archive/"'+(!isDeep?' aria-current="page"':'')+'>Archive <span>'+archived.length+'</span></a>'+
  '<a href="'+r+'deep-archive/"'+(isDeep?' aria-current="page"':'')+'>Deep Archive <span>'+deep.length+'</span></a>'+
  '</nav>';
 const renderItem=(a,index)=>'<div class="archive-story-item"><time class="archive-story-date" datetime="'+esc(a.publishedAt)+'">PUBLISHED '+esc(a.publishedAt)+'</time>'+listCard(a,r,index)+'</div>';
 let rows='';
 if(isDeep){
  const years=[...new Set(items.map(a=>a.publishedAt.slice(0,4)))];
  rows=years.map(year=>{
   const list=items.filter(a=>a.publishedAt.startsWith(year));
   return '<section class="archive-year-group" aria-label="Articles published in '+year+'"><h2>'+year+' <span>'+list.length+' '+(list.length===1?'STORY':'STORIES')+'</span></h2>'+list.map(renderItem).join('')+'</section>';
  }).join('');
 }else{
  const months=[...new Set(items.map(a=>a.publishedAt.slice(0,7)))];
  rows=months.map(month=>{
   const list=items.filter(a=>a.publishedAt.startsWith(month));
   const [y,m]=month.split('-').map(Number);
   const title=new Date(Date.UTC(y,m-1,1)).toLocaleString('en-US',{month:'long',year:'numeric',timeZone:'UTC'});
   return '<section class="archive-year-group" aria-label="Articles published in '+esc(title)+'"><h2>'+esc(title)+' <span>'+list.length+' '+(list.length===1?'STORY':'STORIES')+'</span></h2>'+list.map(renderItem).join('')+'</section>';
  }).join('');
 }
 const description=isDeep?'Stories published at least one calendar year ago, organized by publication year.':'Stories published at least one calendar month ago and less than one year ago, organized by publication month.';
 const emptyMessage=isDeep?'Nothing has reached its one-year anniversary yet. Older reporting will appear here automatically.':'Nothing has reached its one-month anniversary yet. Articles move here automatically when they do.';
 const main=items.length?'<div class="archive-shelf-count">'+items.length+' '+(items.length===1?'article':'articles')+' in this collection</div>'+rows:'<div class="archive-shelf-empty"><h2>Nothing on this shelf yet.</h2><p>'+emptyMessage+'</p><a href="'+r+'latest/">Read the latest reporting ↗</a></div>';
 const content='<div class="container archive-shelf">'+intro('CIVORA / PAST EDITIONS',title,description,'Articles keep their original URLs, publication dates, credits and corrections. No story is deleted when it moves between shelves.')+links+main+'<div class="archive-shelf-footer"><a href="'+r+'search/">Search every Civora story ↗</a><a href="'+r+'discover/">Explore the Reading Room ↗</a></div></div>';
 files[path]=frame(path,title,description,isDeep?'deep-archive':'archive',content);
};
