const related=library.filter(x=>x.id!==a.id).sort((x,y)=>Number(y.topic===a.topic)-Number(x.topic===a.topic)||Number(y.cat===a.cat)-Number(x.cat===a.cat)).slice(0,3);
const relatedMarkup=related.length?'<section class="reading-continue"><div class="section-heading"><div><span class="section-index">MORE IN THE EDITION</span><h2>Keep exploring</h2></div><a class="text-link" href="'+r+'discover/">Discover more ↗</a></div><div class="reading-next-grid">'+related.map(x=>'<a class="reading-next-card" href="'+articleURL(x,r)+'"><small>'+esc(x.cat)+' / '+label(x)+'</small><strong>'+esc(x.title)+'</strong><span>Read the story ↗</span></a>').join("")+'</div></section>':'';
const content=`<div class="container article-frame" data-story-id="${esc(a.id)}"><div class="article-crumb"><a href="${r}">Home</a><span> / </span><a href="${categoryURL(a,r)}">${esc(a.cat)}</a><span> / </span><a href="${topicURL(a,r)}">${esc(a.topic||a.cat)}</a><span> / Article</span></div><article><header class="article-header">${eyebrow((a.topic||a.cat)+" / "+label(a))}<h1>${esc(a.title)}</h1><p class="article-dek">${esc(a.summary)}</p><div class="article-meta"><span>BY <strong>${esc(a.author||"Civora Editorial")}</strong></span><span>${isSample?"DEMONSTRATION CONTENT":a.publishedAt?`PUBLISHED ${esc(a.publishedAt)}`:"EDITORIAL"}</span></div></header>${archiveNotice}${picture(a,"article-hero")}${isSample?'<div class="sample-disclosure"><strong>Editorial sample.</strong> This article demonstrates Civora’s publishing layout. It is not a freshly reported news story or evidence of a recent event.</div>':""}<div class="article-columns"><div class="article-body">${a.body.map((p,i)=>`<p>${esc(p)}</p>${i===1&&a.body.length>=5?adContainer("inArticle","civora-ad-inarticle"):""}`).join("")}<section class="article-sources"><h2>Sources & further reading</h2>${srcs?`<ul>${srcs}</ul>`:"<p>This article does not currently list external sources.</p>"}<p class="source-caption">Reference links are provided for reader research; their inclusion does not imply endorsement.</p></section></div><aside class="article-rail"><span class="rail-title">THE CIVORA PRINCIPLE</span><p>Journalism should help you understand what we know, how we know it, and what remains uncertain.</p><a href="${r}standards/">Our editorial standards ↗</a></aside></div></article><div class="article-bottom"><a class="button-light dark-button" href="${r+shelfRoute}">← Return to ${shelfName}</a><a class="text-link" href="${topicURL(a,r)}">More in ${esc(a.topic||a.cat)} ↗</a></div>${relatedMarkup}${adContainer("multiplex","civora-ad-multiplex")}</div>`;
