const sitemapPaths=Object.keys(files).filter(x=>x.endsWith(".html")&&!x.startsWith("editor/")&&x!=="search/index.html"&&!sampleFiles.has(x));const domain="https://civoranews.org/"; files["sitemap.xml"]=`<?xml version="1.0" encoding="UTF-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">${sitemapPaths.map(p=>`<url><loc>${domain+(p==="index.html"?"":p.replace(/index\.html$/,""))}</loc></url>`).join("")}</urlset>`;
