const source=JSON.parse(fs.readFileSync("content/articles.json","utf8"));if(!Array.isArray(source.articles))throw Error("content/articles.json must contain an articles array");const ids=new Set();for(const a of source.articles){if(!a.id||!/^[a-z0-9]+(?:-[a-z0-9]+)*$/.test(a.id)||ids.has(a.id))throw Error("Invalid or duplicate article id: "+a.id);ids.add(a.id);if(!["draft","sample","published"].includes(a.status))throw Error("Invalid article status: "+a.id);if(!a.title||!a.cat||!a.summary||!Array.isArray(a.body)||!a.body.length)throw Error("Missing required article fields: "+a.id);if(a.status==="published"&&!/^\d{4}-\d{2}-\d{2}$/.test(a.publishedAt||""))throw Error("Published article missing publication date: "+a.id);}const output=generateSite(source.articles);let changes=[];for(const [file,content] of Object.entries(output)){if(process.argv.includes("--check")){if(!fs.existsSync(file)||fs.readFileSync(file,"utf8")!==content)changes.push(file);}else{fs.mkdirSync(path.dirname(file),{recursive:true});fs.writeFileSync(file,content);}}if(changes.length){console.error("Generated files out of date:\n"+changes.join("\n"));process.exit(1);}console.log((process.argv.includes("--check")?"Verified":"Generated")+" "+Object.keys(output).length+" site files.");